+// return its scalar content (folded scalar semantics: lines joined with ' ').
+function extractJobIf(yml) {
+    var lines = yml.split('\n');
+    for (var i = 0; i < lines.length; i++) {
+        if (/^ {4}if: >-\s*$/.test(lines[i])) {
