            '    - cron: "*/10 * * * *"',
            '  workflow_dispatch:',
            'jobs:',
            '  sm:',
            '    steps:',
            '      - run: echo push'
        ].join('\n');
        assert.deepEqual(lint.extractTriggers(yml), ['schedule', 'workflow_dispatch']);
    });

    test('a nested "on:" below the top level is not the trigger block', function () {
        var yml = [
            'jobs:',
            '  a:',
            '    steps:',
